import React, { useState } from 'react';
import { Header } from './components/Header';
import { TerminalView } from './components/TerminalView';
import { GitCollectorView } from './components/GitCollectorView';
import { AIEngineView } from './components/AIEngineView';
import { DocumentEngineView } from './components/DocumentEngineView';
import { ArchitectureView } from './components/ArchitectureView';
import { TeamVivaView } from './components/TeamVivaView';
import { SAMPLE_REPOSITORIES, INITIAL_VVA_CONFIG } from './data/mockRepositories';
import { Repository, GitCommit, VVAConfig, ProjectDataJSON, AIStructuredResponse } from './types/vva';
import { buildProjectDataJSON, generateStructuredAIResponse } from './utils/orchestrator';

export default function App() {
  const [repositories, setRepositories] = useState<Repository[]>(SAMPLE_REPOSITORIES);
  const [currentRepo, setCurrentRepo] = useState<Repository>(SAMPLE_REPOSITORIES[0]);
  const [selectedCommit, setSelectedCommit] = useState<GitCommit>(SAMPLE_REPOSITORIES[0].commits[0]);
  const [vvaConfig, setVvaConfig] = useState<VVAConfig>(INITIAL_VVA_CONFIG);
  const [activeTab, setActiveTab] = useState<string>('terminal');
  const [isInitialized, setIsInitialized] = useState<boolean>(true);
  const [isWatchMode, setIsWatchMode] = useState<boolean>(false);
  const [isRunningReport, setIsRunningReport] = useState<boolean>(false);

  // Computed / cached data
  const initialProjectData = buildProjectDataJSON(currentRepo, selectedCommit, vvaConfig);
  const initialAIResponse = generateStructuredAIResponse(initialProjectData, vvaConfig.aiProvider);

  const [lastProjectData, setLastProjectData] = useState<ProjectDataJSON>(initialProjectData);
  const [lastAIResponse, setLastAIResponse] = useState<AIStructuredResponse>(initialAIResponse);

  const handleAddNewCommit = (newCommit: GitCommit) => {
    const updatedRepos = repositories.map(repo => {
      if (repo.id === currentRepo.id) {
        return {
          ...repo,
          commits: [newCommit, ...repo.commits]
        };
      }
      return repo;
    });

    setRepositories(updatedRepos);
    const updatedCurrent = updatedRepos.find(r => r.id === currentRepo.id) || currentRepo;
    setCurrentRepo(updatedCurrent);
    setSelectedCommit(newCommit);

    // Recompute
    const pData = buildProjectDataJSON(updatedCurrent, newCommit, vvaConfig);
    const aiResp = generateStructuredAIResponse(pData, vvaConfig.aiProvider);
    setLastProjectData(pData);
    setLastAIResponse(aiResp);
  };

  const handleSelectCommit = (commit: GitCommit) => {
    setSelectedCommit(commit);
    const pData = buildProjectDataJSON(currentRepo, commit, vvaConfig);
    const aiResp = generateStructuredAIResponse(pData, vvaConfig.aiProvider);
    setLastProjectData(pData);
    setLastAIResponse(aiResp);
  };

  const handleExecuteReport = async (format?: string) => {
    setIsRunningReport(true);
    return new Promise<void>((resolve) => {
      setTimeout(() => {
        const pData = buildProjectDataJSON(currentRepo, selectedCommit, vvaConfig);
        const aiResp = generateStructuredAIResponse(pData, vvaConfig.aiProvider);
        setLastProjectData(pData);
        setLastAIResponse(aiResp);
        setIsRunningReport(false);
        resolve();
      }, 700);
    });
  };

  const handleHeaderRunReport = async () => {
    await handleExecuteReport();
    setActiveTab('documents');
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col font-sans">
      {/* Top Bar Contract Header */}
      <Header
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        onRunReport={handleHeaderRunReport}
        isRunningReport={isRunningReport}
        repoName={currentRepo.name}
        currentBranch={currentRepo.currentBranch}
      />

      {/* Main Viewport Content */}
      <main className="flex-1 flex flex-col">
        {activeTab === 'terminal' && (
          <TerminalView
            currentRepo={currentRepo}
            selectedCommit={selectedCommit}
            vvaConfig={vvaConfig}
            isInitialized={isInitialized}
            setIsInitialized={setIsInitialized}
            onExecuteReport={handleExecuteReport}
            isWatchMode={isWatchMode}
            setIsWatchMode={setIsWatchMode}
            lastProjectData={lastProjectData}
            lastAIResponse={lastAIResponse}
            onSelectTab={setActiveTab}
          />
        )}

        {activeTab === 'collector' && (
          <GitCollectorView
            repositories={repositories}
            currentRepo={currentRepo}
            onSelectRepo={(r) => {
              setCurrentRepo(r);
              setSelectedCommit(r.commits[0]);
              const pData = buildProjectDataJSON(r, r.commits[0], vvaConfig);
              const aiResp = generateStructuredAIResponse(pData, vvaConfig.aiProvider);
              setLastProjectData(pData);
              setLastAIResponse(aiResp);
            }}
            selectedCommit={selectedCommit}
            onSelectCommit={handleSelectCommit}
            vvaConfig={vvaConfig}
            onAddNewCommit={handleAddNewCommit}
          />
        )}

        {activeTab === 'ai-engine' && (
          <AIEngineView
            currentRepo={currentRepo}
            selectedCommit={selectedCommit}
            vvaConfig={vvaConfig}
            lastAIResponse={lastAIResponse}
            onUpdateAIResponse={setLastAIResponse}
          />
        )}

        {activeTab === 'documents' && (
          <DocumentEngineView
            currentRepo={currentRepo}
            selectedCommit={selectedCommit}
            projectData={lastProjectData}
            aiAnalysis={lastAIResponse}
            vvaConfig={vvaConfig}
          />
        )}

        {activeTab === 'architecture' && <ArchitectureView />}

        {activeTab === 'team' && <TeamVivaView />}
      </main>

      {/* Quiet, Clean Editorial Footer (Anti-Slop Restraint) */}
      <footer className="border-t border-slate-900 bg-slate-950 px-6 py-4 text-xs text-slate-500 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-2">
          <span className="font-semibold text-slate-400">VVA — Version &amp; Workflow Automator</span>
          <span>·</span>
          <span>Orchestrating Git Commit History into Technical Documents</span>
        </div>
        <div className="flex items-center gap-4 text-slate-400 font-mono text-[11px]">
          <span>Lead Orchestrator: Abhiram Binil</span>
          <span>·</span>
          <span>AI Engine: Vishnu G Pillai</span>
          <span>·</span>
          <span>Doc Engine: Vinay Bisht</span>
        </div>
      </footer>
    </div>
  );
}

#!/usr/bin/env node

import { initCommand } from './commands/init.js';
import { statusCommand } from './commands/status.js';
import { reportCommand } from './commands/report.js';
import { watchCommand } from './commands/watch.js';

const args = process.argv.slice(2);
const command = args[0]?.toLowerCase();

function printHelp() {
  console.log(`
VVA — Version & Workflow Automator [Node.js Orchestrator CLI v1.0.0]
Usage: vva <command> [options]

Commands:
  init                     Initialize .vva/ configuration and output directories
  status                   Inspect repository branch, active commit, and VVA status
  report [options]         Execute full pipeline: Git -> AI -> PDF/DOCX/PPTX
  watch                    Daemon mode: monitor Git commits and auto-generate reports
  help                     Show this help guide

Report Options:
  --commit <hash>          Specify target commit hash (default: HEAD)
  --format <pdf|docx|pptx|all> (default: all)
  --dry-run                Collect Git data only without invoking Python AI
`);
}

async function main() {
  if (!command || command === 'help' || command === '--help' || command === '-h') {
    printHelp();
    process.exit(0);
  }

  try {
    if (command === 'init') {
      const res = await initCommand();
      console.log(`\x1b[32m✓ VVA successfully initialized in ${res.root}\x1b[0m`);
      console.log(`  Created directory: .vva/`);
      console.log(`  Created config:    .vva/config.json`);
      console.log(`  Created output:    .vva/output/`);
      console.log(`\nRun 'vva status' to check environment or 'vva report' to generate documents.`);
      process.exit(0);
    }

    if (command === 'status') {
      const res = await statusCommand();
      if (!res.isGitRepo) {
        console.error(`\x1b[31mError: ${res.message}\x1b[0m`);
        process.exit(1);
      }

      console.log('\x1b[36m=== VVA Repository Status ===\x1b[0m');
      console.log(`Repository:      ${res.repositoryName} (${res.repositoryPath})`);
      console.log(`Current Branch:  ${res.branch}`);
      if (res.latestCommit) {
        console.log(`HEAD Commit:     ${res.latestCommit.shortHash} - "${res.latestCommit.message}"`);
        console.log(`Author:          ${res.latestCommit.author} <${res.latestCommit.email}>`);
        console.log(`Date:            ${res.latestCommit.date}`);
      } else {
        console.log(`HEAD Commit:     No commits found (empty repository)`);
      }
      console.log(`Working Tree:    ${res.uncommittedCount === 0 ? '\x1b[32mClean (0 uncommitted changes)\x1b[0m' : `\x1b[33m${res.uncommittedCount} uncommitted change(s)\x1b[0m`}`);
      console.log(`VVA Environment: ${res.isInitialized ? '\x1b[32mInitialized (.vva/)\x1b[0m' : '\x1b[33mNot initialized (run vva init)\x1b[0m'}`);
      console.log(`Python Runtime:  ${res.pythonReady ? `\x1b[32m${res.pythonBinary}\x1b[0m` : '\x1b[31mNot found\x1b[0m'}`);
      console.log('=============================');
      process.exit(0);
    }

    if (command === 'report') {
      const commitIndex = args.indexOf('--commit');
      const targetCommit = commitIndex !== -1 ? args[commitIndex + 1] : 'HEAD';

      const formatIndex = args.indexOf('--format');
      const format = formatIndex !== -1 ? args[formatIndex + 1] : 'all';

      const dryRun = args.includes('--dry-run');

      console.log(`\x1b[36m[Stage 1/4] Git Data Collector: Inspecting commit ${targetCommit}...\x1b[0m`);
      const res = await reportCommand({ commit: targetCommit, format, dryRun });

      if (res.dryRun) {
        console.log(`\x1b[32m✓ Dry-run completed. Saved project data to ${res.projectDataPath}\x1b[0m`);
        console.log(`  Analyzed commit: ${res.analyzedCommit.slice(0, 7)} (${res.changedFiles} files)`);
        process.exit(0);
      }

      console.log(`\x1b[32m✓ Pipeline Execution Succeeded!\x1b[0m`);
      console.log(`Repository:      ${res.repository}`);
      console.log(`Commit:          ${res.analyzedCommit.slice(0, 7)} ("${res.commitMessage}")`);
      console.log(`Feature Analyzed: "${res.aiTitle}"`);
      console.log(`Project Data:    ${res.projectDataPath}`);
      console.log(`AI Response:     ${res.aiOutputPath}`);
      console.log(`\n\x1b[32mGenerated Artifacts:\x1b[0m`);
      for (const f of res.generatedFiles) {
        console.log(`  → ${f.filename} (${(f.sizeBytes / 1024).toFixed(1)} KB) in ${f.path}`);
      }
      process.exit(0);
    }

    if (command === 'watch') {
      console.log('\x1b[36m[vva watch] Starting Git commit monitor daemon. Press Ctrl+C to exit.\x1b[0m');
      await watchCommand();
      // Keep process open
      return;
    }

    console.error(`\x1b[31mUnknown command: '${command}'. Type 'vva help' for usage.\x1b[0m`);
    process.exit(1);
  } catch (error) {
    console.error(`\x1b[31mError: ${error.message}\x1b[0m`);
    process.exit(1);
  }
}

main();

import fs from 'node:fs/promises';
import path from 'node:path';
import { isGitRepo, getRepoRoot } from '../core/git.js';
import { getPythonBinary } from '../core/python.js';

export async function initCommand(cwd = process.cwd()) {
  const isRepo = await isGitRepo(cwd);
  if (!isRepo) {
    throw new Error(`Cannot initialize VVA: directory '${cwd}' is not a Git repository. Run 'git init' first.`);
  }

  const root = await getRepoRoot(cwd);
  const vvaDir = path.join(root, '.vva');
  const logsDir = path.join(vvaDir, 'logs');
  const outputDir = path.join(vvaDir, 'output');
  const configFile = path.join(vvaDir, 'config.json');

  await fs.mkdir(vvaDir, { recursive: true });
  await fs.mkdir(logsDir, { recursive: true });
  await fs.mkdir(outputDir, { recursive: true });

  const pythonBin = await getPythonBinary();

  const defaultConfig = {
    vvaVersion: '1.0.0',
    initializedAt: new Date().toISOString(),
    defaultFormat: 'all',
    outputDir: '.vva/output',
    pythonBinary: pythonBin,
    aiProvider: 'nvidia',
    aiModel: 'meta/llama-3.1-70b-instruct',
    maxDiffSizeBytes: 1048576,
    team: {
      orchestrator: 'Abhiram Binil (Person 1)',
      aiEngine: 'Vishnu G Pillai (Person 2)',
      documentEngine: 'Vinay Bisht (Person 3)'
    }
  };

  await fs.writeFile(configFile, JSON.stringify(defaultConfig, null, 2), 'utf8');

  // Also ensure .gitignore ignores .vva logs and heavy artifacts if preferred
  return {
    success: true,
    root,
    vvaDir,
    config: defaultConfig
  };
}

import fs from 'node:fs/promises';
import path from 'node:path';
import { getRepoRoot } from '../core/git.js';
import { collectGitData } from '../core/collector.js';
import { invokePythonModule } from '../core/python.js';

export async function reportCommand(options = {}, cwd = process.cwd()) {
  const root = await getRepoRoot(cwd);
  const vvaDir = path.join(root, '.vva');
  const outputDir = path.join(vvaDir, 'output');
  const configFile = path.join(vvaDir, 'config.json');

  // 1. Ensure .vva is initialized
  let config = {};
  try {
    const rawConfig = await fs.readFile(configFile, 'utf8');
    config = JSON.parse(rawConfig);
  } catch {
    // Auto-create directory structure if running in uninitialized repo
    await fs.mkdir(outputDir, { recursive: true });
    config = { defaultFormat: 'all', maxDiffSizeBytes: 1048576 };
  }

  const targetCommit = options.commit || 'HEAD';
  const format = options.format || config.defaultFormat || 'all';

  // 2. Stage 1/4: Git Data Collection
  const projectData = await collectGitData(targetCommit, root, {
    maxDiffSizeBytes: config.maxDiffSizeBytes
  });

  const projectDataPath = path.join(outputDir, 'project-data.json');
  await fs.writeFile(projectDataPath, JSON.stringify(projectData, null, 2), 'utf8');

  if (options.dryRun) {
    return {
      dryRun: true,
      projectDataPath,
      analyzedCommit: projectData.analyzedCommit,
      changedFiles: projectData.changedFiles.length
    };
  }

  // 3. Stage 2/4: Invoke Python AI Engine
  const aiOutputPath = path.join(outputDir, 'ai-response.json');
  await invokePythonModule(
    'ai/ai_engine.py',
    ['--input', projectDataPath, '--output', aiOutputPath],
    root
  );

  // Validate that ai-response.json was created and is valid JSON
  let aiData;
  try {
    const rawAi = await fs.readFile(aiOutputPath, 'utf8');
    aiData = JSON.parse(rawAi);
    if (!aiData.title || !aiData.summary || !Array.isArray(aiData.technicalChanges)) {
      throw new Error('AI response JSON is missing required fields.');
    }
  } catch (err) {
    throw new Error(`AI Engine verification failed: ${err.message}`);
  }

  // 4. Stage 3/4: Invoke Python Document Generation Engine
  const docResultRaw = await invokePythonModule(
    'document_engine/document_engine.py',
    [
      '--ai-input', aiOutputPath,
      '--project-input', projectDataPath,
      '--output-dir', outputDir,
      '--format', format
    ],
    root
  );

  let docResults = [];
  try {
    docResults = JSON.parse(docResultRaw);
  } catch {
    // If output contained non-JSON debug logs, check disk files
  }

  // 5. Verify generated files on disk
  const shortHash = projectData.analyzedCommit.slice(0, 7);
  const repoName = projectData.repository;
  const expectedFiles = [];

  if (format === 'pdf' || format === 'all') {
    expectedFiles.push(path.join(outputDir, `${repoName}_${shortHash}_report.pdf`));
  }
  if (format === 'docx' || format === 'all') {
    expectedFiles.push(path.join(outputDir, `${repoName}_${shortHash}_synopsis.docx`));
  }
  if (format === 'pptx' || format === 'all') {
    expectedFiles.push(path.join(outputDir, `${repoName}_${shortHash}_presentation.pptx`));
  }

  const verifiedFiles = [];
  for (const f of expectedFiles) {
    try {
      const stat = await fs.stat(f);
      verifiedFiles.push({
        path: f,
        filename: path.basename(f),
        sizeBytes: stat.size
      });
    } catch {
      // File was not generated
    }
  }

  return {
    success: true,
    repository: projectData.repository,
    analyzedCommit: projectData.analyzedCommit,
    commitMessage: projectData.commitMessage,
    projectDataPath,
    aiOutputPath,
    aiTitle: aiData.title,
    generatedFiles: verifiedFiles
  };
}

import fs from 'node:fs/promises';
import path from 'node:path';
import { isGitRepo, getRepoRoot, getCurrentBranch, execGit, getCommitDetails } from '../core/git.js';
import { getPythonBinary } from '../core/python.js';

export async function statusCommand(cwd = process.cwd()) {
  const isRepo = await isGitRepo(cwd);
  if (!isRepo) {
    return {
      isGitRepo: false,
      message: `Directory '${cwd}' is not inside a Git repository.`
    };
  }

  const root = await getRepoRoot(cwd);
  const branch = await getCurrentBranch(root);
  const configFile = path.join(root, '.vva', 'config.json');

  let isInitialized = false;
  let config = null;
  try {
    const raw = await fs.readFile(configFile, 'utf8');
    config = JSON.parse(raw);
    isInitialized = true;
  } catch {
    isInitialized = false;
  }

  let latestCommit = null;
  try {
    const headHash = await execGit(['rev-parse', 'HEAD'], root);
    latestCommit = await getCommitDetails(headHash, root);
  } catch {
    latestCommit = null; // Repo might have 0 commits
  }

  let uncommittedCount = 0;
  try {
    const statusRaw = await execGit(['status', '--porcelain'], root);
    uncommittedCount = statusRaw ? statusRaw.split('\n').filter(Boolean).length : 0;
  } catch {
    //
  }

  let pythonReady = false;
  let pythonBin = null;
  try {
    pythonBin = await getPythonBinary();
    pythonReady = true;
  } catch {
    pythonReady = false;
  }

  return {
    isGitRepo: true,
    repositoryName: path.basename(root),
    repositoryPath: root,
    branch,
    isInitialized,
    config,
    latestCommit,
    uncommittedCount,
    pythonReady,
    pythonBinary: pythonBin
  };
}

import { getRepoRoot, execGit } from '../core/git.js';
import { reportCommand } from './report.js';

/**
 * Watcher daemon that monitors Git HEAD ref updates.
 */
export async function watchCommand(options = {}, cwd = process.cwd(), onCommitDetected) {
  const root = await getRepoRoot(cwd);
  let lastKnownCommit = null;

  try {
    lastKnownCommit = await execGit(['rev-parse', 'HEAD'], root);
  } catch {
    //
  }

  const pollIntervalMs = options.intervalMs || 4000;
  let isRunning = true;

  const intervalId = setInterval(async () => {
    if (!isRunning) return;
    try {
      const currentCommit = await execGit(['rev-parse', 'HEAD'], root);
      if (currentCommit && currentCommit !== lastKnownCommit) {
        lastKnownCommit = currentCommit;
        if (onCommitDetected) {
          onCommitDetected(currentCommit);
        } else {
          console.log(`[vva watch] New commit detected: ${currentCommit.slice(0, 7)}. Generating reports...`);
          await reportCommand({ commit: currentCommit, format: options.format || 'all' }, root);
        }
      }
    } catch {
      //
    }
  }, pollIntervalMs);

  return {
    stop: () => {
      isRunning = false;
      clearInterval(intervalId);
    }
  };
}

import React, { useState } from 'react';
import { Cpu, CheckCircle2, AlertTriangle, Sparkles, Code2, Eye, ShieldCheck, Copy, Check } from 'lucide-react';
import { Repository, GitCommit, AIStructuredResponse, VVAConfig, ProjectDataJSON } from '../types/vva';
import { buildProjectDataJSON, generateStructuredAIResponse } from '../utils/orchestrator';

interface AIEngineViewProps {
  currentRepo: Repository;
  selectedCommit: GitCommit;
  vvaConfig: VVAConfig;
  lastAIResponse: AIStructuredResponse | null;
  onUpdateAIResponse: (response: AIStructuredResponse) => void;
}

export const AIEngineView: React.FC<AIEngineViewProps> = ({
  currentRepo,
  selectedCommit,
  vvaConfig,
  lastAIResponse,
  onUpdateAIResponse,
}) => {
  const [provider, setProvider] = useState<'nvidia' | 'gemini'>(vvaConfig.aiProvider);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [copiedJson, setCopiedJson] = useState(false);

  const projectData: ProjectDataJSON = buildProjectDataJSON(currentRepo, selectedCommit, vvaConfig);
  const activeResponse: AIStructuredResponse = lastAIResponse || generateStructuredAIResponse(projectData, provider);

  const handleRunAnalysis = () => {
    setIsAnalyzing(true);
    setTimeout(() => {
