                    lineClass = 'text-cyan-400 font-semibold';
                    bgClass = 'bg-cyan-950/20';
                  }

                  return (
                    <div key={i} className={`px-2 py-0.5 rounded-sm ${bgClass} ${lineClass} whitespace-pre-wrap`}>
                      {line}
                    </div>
                  );
                })}
