import path from 'node:path';
import {
  isGitRepo,
  getRepoRoot,
  getCurrentBranch,
  getParentCommit,
  getCommitDetails,
  getCommitChangedFiles,
  getFileContentAtCommit,
  getCommitDiff,
  getCommitStats,
  execGit
} from './git.js';

const DEFAULT_MAX_DIFF_BYTES = 1024 * 1024; // 1MB payload cap

/**
 * Collects complete, traceable Git data for a given commit.
 * @param {string} [targetCommit] Commit hash or reference (defaults to HEAD)
 * @param {string} [cwd] Working directory
 * @param {object} [options] Configuration overrides
 */
export async function collectGitData(targetCommit = 'HEAD', cwd = process.cwd(), options = {}) {
  const isRepo = await isGitRepo(cwd);
  if (!isRepo) {
    throw new Error(`Directory '${cwd}' is not inside a Git repository. Run 'git init' or navigate to a repository.`);
  }

  const repoRoot = await getRepoRoot(cwd);
  const repoName = path.basename(repoRoot);
  const branch = await getCurrentBranch(repoRoot);

  // Resolve target commit reference to full 40-character SHA
  const resolvedCommitHash = await execGit(['rev-parse', targetCommit], repoRoot);
  const parentHash = await getParentCommit(resolvedCommitHash, repoRoot);

  // Extract metadata and stats
  const metadata = await getCommitDetails(resolvedCommitHash, repoRoot);
  const stats = await getCommitStats(resolvedCommitHash, repoRoot);
  const changedFilesMeta = await getCommitChangedFiles(resolvedCommitHash, repoRoot);

  const warnings = [];

  // Collect commit-specific file contents
  const changedFiles = [];
  for (const item of changedFilesMeta) {
    const isDeleted = item.status === 'D';
    let content = await getFileContentAtCommit(resolvedCommitHash, item.file, isDeleted, repoRoot);

    // Safeguard against huge single files
    if (content.length > 500 * 1024) {
      content = content.slice(0, 500 * 1024) + '\n\n[VVA Warning: File content truncated exceeding 500KB]';
      warnings.push(`File ${item.file} content truncated for payload safety.`);
    }

    // Determine line count delta
    let additions = 0;
    let deletions = 0;
    try {
      const numstatRaw = await execGit(['diff-tree', '--numstat', resolvedCommitHash, '--', item.file], repoRoot);
      const [addStr, delStr] = numstatRaw.split('\t');
      additions = addStr && addStr !== '-' ? parseInt(addStr, 10) : 0;
      deletions = delStr && delStr !== '-' ? parseInt(delStr, 10) : 0;
    } catch {
      // Fallback
    }

    changedFiles.push({
      file: item.file,
      status: item.status,
      additions,
      deletions,
      content
    });
  }

  // Collect unified diff
  let diff = await getCommitDiff(resolvedCommitHash, repoRoot);
  const maxDiffBytes = options.maxDiffSizeBytes || DEFAULT_MAX_DIFF_BYTES;
  if (Buffer.byteLength(diff, 'utf8') > maxDiffBytes) {
    diff = diff.slice(0, maxDiffBytes) + '\n\n[VVA Warning: Diff patch truncated due to maxDiffSizeBytes limit]';
    warnings.push(`Unified diff exceeded ${maxDiffBytes} bytes and was safely truncated.`);
  }

  return {
    vvaVersion: '1.0.0',
    timestamp: new Date().toISOString(),
    repository: repoName,
    repositoryPath: repoRoot,
    branch,
    analyzedCommit: resolvedCommitHash,
    parentCommit: parentHash,
    author: {
      name: metadata.author,
      email: metadata.email,
      date: metadata.date
    },
    commitMessage: metadata.message,
    summary: {
      filesChanged: stats.filesChanged || changedFiles.length,
      insertions: stats.insertions,
      deletions: stats.deletions
    },
    changedFiles,
    diff,
    ...(warnings.length > 0 ? { warnings } : {})
  };
}

import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import path from 'node:path';

const execFileAsync = promisify(execFile);

/**
 * Executes a Git command safely using argument arrays to prevent shell injection.
 * @param {string[]} args Git subcommands and arguments
 * @param {string} cwd Working directory
 * @returns {Promise<string>} stdout output
 */
export async function execGit(args, cwd = process.cwd()) {
  try {
    const { stdout } = await execFileAsync('git', args, {
      cwd,
      maxBuffer: 20 * 1024 * 1024, // 20MB buffer for diffs
      env: { ...process.env, LANG: 'C.UTF-8' }
    });
    return stdout.trim();
  } catch (error) {
    throw new Error(`Git command failed [git ${args.join(' ')}]: ${error.stderr || error.message}`);
  }
}

/**
 * Checks if a directory is inside a Git working tree.
 */
export async function isGitRepo(cwd = process.cwd()) {
  try {
    const res = await execGit(['rev-parse', '--is-inside-work-tree'], cwd);
    return res === 'true';
  } catch {
    return false;
  }
}

/**
 * Retrieves the absolute top-level directory of the Git repository.
 */
export async function getRepoRoot(cwd = process.cwd()) {
  return await execGit(['rev-parse', '--show-toplevel'], cwd);
}

/**
 * Retrieves the current branch name (or HEAD detached hash).
 */
export async function getCurrentBranch(cwd = process.cwd()) {
  try {
    const branch = await execGit(['rev-parse', '--abbrev-ref', 'HEAD'], cwd);
    return branch !== 'HEAD' ? branch : await execGit(['rev-parse', '--short', 'HEAD'], cwd);
  } catch {
    return 'unknown';
  }
}

/**
 * Retrieves parent commit hash if available.
 */
export async function getParentCommit(commitHash, cwd = process.cwd()) {
  try {
    return await execGit(['rev-parse', '--verify', '--quiet', `${commitHash}^`], cwd);
  } catch {
    // Initial/root commit has no parent
    return null;
  }
}

/**
 * Retrieves detailed commit metadata for a specific commit hash.
 */
export async function getCommitDetails(commitHash, cwd = process.cwd()) {
  const delimiter = '---VVA_DELIM---';
  const format = `%H${delimiter}%h${delimiter}%an${delimiter}%ae${delimiter}%ad${delimiter}%B`;
  const raw = await execGit(['show', '-s', `--format=${format}`, '--date=iso-strict', commitHash], cwd);

  const [hash, shortHash, authorName, authorEmail, date, ...msgParts] = raw.split(delimiter);
  return {
    hash: hash.trim(),
    shortHash: shortHash.trim(),
    author: authorName.trim(),
    email: authorEmail.trim(),
    date: date.trim(),
    message: msgParts.join(delimiter).trim()
  };
}

/**
 * Retrieves changed files with their status flags (A, M, D, R) for a commit.
 */
export async function getCommitChangedFiles(commitHash, cwd = process.cwd()) {
  const isRoot = !(await getParentCommit(commitHash, cwd));
  const diffArgs = isRoot
    ? ['diff-tree', '--no-commit-id', '--name-status', '-r', '--root', commitHash]
    : ['diff-tree', '--no-commit-id', '--name-status', '-r', commitHash];

  const raw = await execGit(diffArgs, cwd);
  if (!raw) return [];

  const lines = raw.split('\n').filter(Boolean);
  return lines.map(line => {
    const parts = line.split('\t');
    const rawStatus = parts[0];
    const filePath = parts[1];

    // Normalize status: A, M, D, R
    let status = 'M';
    if (rawStatus.startsWith('A')) status = 'A';
    else if (rawStatus.startsWith('D')) status = 'D';
    else if (rawStatus.startsWith('R')) status = 'R';

    return {
      status,
      file: filePath
    };
  });
}

/**
 * Retrieves the committed version of a file at a specific commit.
 * For deleted files, inspects the parent commit.
 */
export async function getFileContentAtCommit(commitHash, filePath, isDeleted = false, cwd = process.cwd()) {
  try {
    const targetRef = isDeleted ? `${commitHash}^:${filePath}` : `${commitHash}:${filePath}`;
    return await execGit(['show', targetRef], cwd);
  } catch (error) {
    return `[VVA Warning: Could not retrieve committed content for ${filePath}: ${error.message}]`;
  }
}

/**
 * Retrieves the exact unified patch for a commit.
 */
export async function getCommitDiff(commitHash, cwd = process.cwd()) {
  const isRoot = !(await getParentCommit(commitHash, cwd));
  const args = isRoot
    ? ['show', '--format=', '--patch', '--root', commitHash]
    : ['show', '--format=', '--patch', commitHash];

  return await execGit(args, cwd);
}

/**
 * Retrieves insertion and deletion stats for a commit.
 */
export async function getCommitStats(commitHash, cwd = process.cwd()) {
  const isRoot = !(await getParentCommit(commitHash, cwd));
  const args = isRoot
    ? ['diff-tree', '--shortstat', '--root', commitHash]
    : ['diff-tree', '--shortstat', commitHash];

  try {
    const raw = await execGit(args, cwd);
    // e.g., " 2 files changed, 28 insertions(+), 4 deletions(-)"
    const filesMatch = raw.match(/(\d+)\s+file/);
    const insMatch = raw.match(/(\d+)\s+insertion/);
    const delMatch = raw.match(/(\d+)\s+deletion/);

    return {
      filesChanged: filesMatch ? parseInt(filesMatch[1], 10) : 0,
      insertions: insMatch ? parseInt(insMatch[1], 10) : 0,
      deletions: delMatch ? parseInt(delMatch[1], 10) : 0
    };
  } catch {
    return { filesChanged: 0, insertions: 0, deletions: 0 };
  }
}

import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import path from 'node:path';
import fs from 'node:fs/promises';

const execFileAsync = promisify(execFile);

/**
 * Discovers the active Python binary (python3 or python).
 */
export async function getPythonBinary() {
  try {
    await execFileAsync('python3', ['--version']);
    return 'python3';
  } catch {
    try {
      await execFileAsync('python', ['--version']);
      return 'python';
    } catch {
      throw new Error('Python 3 is required but neither "python3" nor "python" was found in PATH.');
    }
  }
}

/**
 * Invokes a Python script with structured JSON arguments via IPC.
 * @param {string} scriptRelativePath Relative path from repo root (e.g., 'ai/ai_engine.py')
 * @param {string[]} args Array of command-line arguments
 * @param {string} cwd Working directory
 */
export async function invokePythonModule(scriptRelativePath, args = [], cwd = process.cwd()) {
  const pythonBin = await getPythonBinary();
  const scriptPath = path.resolve(cwd, scriptRelativePath);

  try {
    await fs.access(scriptPath);
  } catch {
    throw new Error(`Python module not found at: ${scriptPath}`);
  }

  try {
    const { stdout, stderr } = await execFileAsync(pythonBin, [scriptPath, ...args], {
      cwd,
      maxBuffer: 20 * 1024 * 1024,
      env: { ...process.env, PYTHONUNBUFFERED: '1' }
    });

    if (stderr && stderr.trim().length > 0) {
      // Log warning if non-fatal
    }

    return stdout.trim();
  } catch (error) {
    throw new Error(`Python execution failed for ${scriptRelativePath}: ${error.stderr || error.message}`);
  }
}

